    // The second copy is a duplicate of the first, so only one copy is sent here.
    const r = await app.call('POST', '/groups/trip/import', { entries: entries.slice(0, 1), skip_recorded: true, dry_run })
    assert.equal(r.status, status)
    assert.deepEqual(r.body, { expenses: [], payments: [], skipped: [0], balances: { Ann: 6.66, Ben: -3.33, Cara: -3.33 } })
  }
  assert.equal(readFileSync(data.file, 'utf8'), before)
})

